namespace CheckoutPricing.Domain;

public sealed class LoyaltyDiscountPolicy
{
    public int DiscountFor(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents * PercentOf(tier) / 100;

    private static int PercentOf(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        _ => 0
    };
}
EOF
