namespace CheckoutPricing.Domain;

public sealed class DiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int LoyaltyCapCents = 2_000;
    private const int WelcomeCents = 500;
    private const int SummerPercent = 10;
    private const int SummerCapCents = 1_500;

    private readonly LoyaltyDiscountPolicy loyalty = new();

    public int DiscountFor(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyPart = LoyaltyPart(subtotalCents, tier);
        var total = loyaltyPart + PromoPart(promoCode, subtotalCents - loyaltyPart);
        return Math.Min(total, subtotalCents);
    }

    private int LoyaltyPart(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(loyalty.DiscountFor(subtotalCents, tier), LoyaltyCapCents);

    private static int PromoPart(string? promoCode, int remainingCents)
    {
        if (string.Equals(promoCode, "WELCOME5", StringComparison.OrdinalIgnoreCase))
        {
            return WelcomeCents;
        }

        if (string.Equals(promoCode, "SUMMER10", StringComparison.OrdinalIgnoreCase))
        {
            return Math.Min(remainingCents * SummerPercent / 100, SummerCapCents);
        }

        return 0;
    }
}

